module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

    parameter ACCUMULATE_COUNT = 4;

    reg [1:0] count;
    reg [9:0] accumulated_sum;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 2'b00;
            accumulated_sum <= 10'b0000000000;
            valid_out <= 1'b0;
        end else begin
            if (valid_in && count < ACCUMULATE_COUNT) begin
                accumulated_sum <= accumulated_sum + data_in;
                count <= count + 1'b1;
            end
            if (count == ACCUMULATE_COUNT) begin
                valid_out <= 1'b1;
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

endmodule
